func caught_count(category: String = "") -> int:
	var count := 0
	for d: Dictionary in DEFS:
		if category != "" and String(d["category"]) != category:
			continue
		if bool(m.critter_collection.get(String(d["id"]), false)):
			count += 1
	return count


