func _action_down() -> bool:
	var down := Input.is_physical_key_pressed(KEY_SPACE) or m.joy_pressed(JOY_BUTTON_A) or m.joy_pressed(JOY_BUTTON_B)
	if m.touch_ui != null and bool(m.touch_ui.action_down):
		down = true
	return down


